mapper.select:
SELECT v.id, v.title, v.cover_url, v.duration_seconds, v.published_at, u.id AS owner_id, u.nickname AS owner_nickname, u.avatar_url AS owner_avatar, COALESCE(s.play_count, 0) AS play_count, COALESCE(s.danmaku_count, 0) AS danmaku_count, COALESCE(s.like_count, 0) AS like_count, COALESCE(s.coin_count, 0) AS coin_count, COALESCE(s.favorite_count, 0) AS favorite_count, COALESCE(s.comment_count, 0) AS comment_count FROM video v JOIN `user` u ON u.id = v.owner_id AND u.deleted_at IS NULL LEFT JOIN video_stats s ON s.video_id = v.id WHERE v.status = 1 AND v.deleted_at IS NULL
AND v.category_id = #{categoryId}
AND v.owner_id = #{ownerId}
AND v.id < #{cursorId}
ORDER BY s.play_count DESC, v.id DESC
ORDER BY v.published_at DESC, v.id DESC
LIMIT #{limit}

SELECT video_id, reaction_type, coin_count
FROM video_reaction
WHERE user_id = #{userId}
  AND video_id IN

    #{vid}
